// src/scripts/fix-ui-issues.js
/**
 * Bulk UI‑audit auto‑fix script (JavaScript version).
 *
 * Reads the JSON audit report generated by `src/utils/uiAudit.ts`
 * (ui-audit-report.json) and applies placeholder fixes for two common
 * accessibility issues:
 *   1️⃣ <a> or <Link> elements missing a destination (`href`/`to`).
 *   2️⃣ Non‑interactive elements (div, span, etc.) that have an `onClick`
 *      handler.
 *
 * The script mutates source files in‑place, adding a `TODO` comment so you
 * can replace the placeholder later with a real route or proper button.
 *
 * Usage (run from the project root):
 *   node src/scripts/fix-ui-issues.js
 */

const fs = require('fs');
const path = require('path');

const REPORT_PATH = path.resolve(
  '/Users/rmpgutah/RMPG Flex/ui-audit-report.json'
);

/** @typedef {{file:string,line:number,column:number,type:string,snippet?:string}} Issue */
function loadReport() {
  if (!fs.existsSync(REPORT_PATH)) {
    console.error('[fix-ui-issues] Report not found at', REPORT_PATH);
    process.exit(1);
  }
  const raw = fs.readFileSync(REPORT_PATH, 'utf-8');
  const data = JSON.parse(raw);
  return Array.isArray(data) ? data : data.issues || [];
}

function applyMissingHref(content, issue) {
  const lines = content.split('\n');
  const idx = issue.line - 1;
  if (idx < 0 || idx >= lines.length) return content;
  const line = lines[idx];
  const updated = line.replace(/<(a|Link)(?![^>]*\b(?:href|to)=)[^>]*>/, (match) => {
    const withHref = match.replace(/<(a|Link)/, `<$1 href="#"`);
    return withHref + ' {/* TODO: add real destination */}';
  });
  lines[idx] = updated;
  return lines.join('\n');
}

function applyNonInteractiveOnClick(content, issue) {
  const lines = content.split('\n');
  const idx = issue.line - 1;
  if (idx < 0 || idx >= lines.length) return content;
  const line = lines[idx];
  const updated = line.replace(/<(div|span|li|section|article)([^>]*)\bonClick=/, (match, tag, rest) => {
    const newTag = `<button${rest} onClick=`;
    return newTag + ' {/* TODO: ensure accessible label */}';
  });
  lines[idx] = updated;
  return lines.join('\n');
}

function main() {
  const issues = loadReport();
  if (issues.length === 0) {
    console.log('[fix-ui-issues] No issues found in the report.');
    return;
  }
  const byFile = new Map();
  for (const issue of issues) {
    if (!byFile.has(issue.file)) byFile.set(issue.file, []);
    byFile.get(issue.file).push(issue);
  }
  for (const [file, fileIssues] of byFile.entries()) {
    const absolutePath = path.resolve(
      file.startsWith('/') ? file : path.join('/Users/rmpgutah/RMPG Flex', file)
    );
    if (!fs.existsSync(absolutePath)) {
      console.warn(`[fix-ui-issues] Skipping missing file: ${absolutePath}`);
      continue;
    }
    let content = fs.readFileSync(absolutePath, 'utf-8');
    for (const issue of fileIssues) {
      if (issue.type === 'missingHref' || issue.type === 'missingHrefOrTo') {
        content = applyMissingHref(content, issue);
      } else if (issue.type === 'nonInteractiveOnClick') {
        content = applyNonInteractiveOnClick(content, issue);
      }
    }
    fs.writeFileSync(absolutePath, content, 'utf-8');
    console.log(`[fix-ui-issues] Updated ${file}`);
  }
}

main();
